    Description:

        Function to make a smaller list which doesn't contain the 'seen' key

    Arguments:

        articles_list {list} : list contains dictionary's with the 'seen' and 'articles' keys

    Returns:

        news_list {list} : list containing just the 'articles' jey from the list in arguments
    """
def news_dictionary_maker(articles_list: list) -> list {
    news_list = [];
    x = 0;
    for i in articles_list {
        if (articles_list[x]['seen'] == 0) {
            news_list.append(articles_list[x]['articles']);
        }
        x = x + 1;
    }
    return news_list;
}

"""Find a pair of elements in iterables seq1 and seq2 with maximum sum.

    @param seq1 - iterable with real values
    @param seq2 - iterable with real values

    @return pos - such that seq1[pos] + seq2[pos] is maximum
    """
def _partition_(seq1: Any, seq2: Any) -> object {
    _sum_ = _max_=_pos_=float("-inf");
    for (pos, ij) in enumerate(zip(seq1, seq2)) {
        _sum_ = sum(ij);
        if (_sum_ > _max_) {
            _max_ = _sum_;
            _pos_ = pos;
        }
    }
    return _pos_;
}

