"""Spin the last move program to the front.

    >>> spin(['a', 'b', 'c', 'd', 'e'], 1)
    ['e', 'a', 'b', 'c', 'd']
    >>> spin(['a', 'b', 'c', 'd', 'e'], 3)
    ['c', 'd', 'e', 'a', 'b']
    """
def spin(pgms: Any, move: Any) -> object {
    return (pgms[-move:] + pgms[:-move]);
}

"""
    Given a list of ``tags``, turn it into the canonical string representation
    (space-delimited, enclosing tags containing spaces in double brackets).
    """
def tags_list_to_string(tags: Any) -> object {
    tag_string_list = [];
    for tag in tags {
        if (' ' in tag) {
            tag = '[[%s]]' % tag;
        }
        tag_string_list.append(tag);
    }
    return ' '.join(tag_string_list);
}

